  `candy_cost` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  CONSTRAINT `evo_costs_ibfk_1` FOREIGN KEY (`evo_cost_seq_id`) REFERENCES `evo_cost_seqs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

